ee:variables.ee:set-variable:
%dw 2.0
output application/java

var meal = vars.mealStatus

// findFood: given a foodId, look up its full nutrition record.
// meal.foods is an array of arrays (each food is wrapped in its own
// single-element array), so we flatten it first to get a flat list
// of food objects before filtering.
fun findFood(foodId) = flatten(meal.foods) filter ((food) -> food.foodId == foodId)

// scaleItem: for one logged meal entry ({foodId, quantityG}),
// look up its reference food data and scale every nutrient value
// from the "per servingSizeG" amount to the "per quantityG actually
// eaten" amount.

fun scaleItem(item) = do {
    // The matching food record (null if not found)
    var food = findFood(item.foodId)[0]
    var factor = if (food != null)
        (item.quantityG as Number) / (food.servingSizeG as Number)
    else 0
    ---
    {
        foodId: item.foodId,
        name: food.name default null,
        quantityG: item.quantityG,
        servingSizeG: food.servingSizeG default null,
        // Multiply every numeric nutrient by the scale factor.
        // null for missing nutrients pass through unchanged
        nutrients: if (food != null)
            food.nutrients mapObject ((value, key) ->
                { (key): if (value is Number) value * factor else value }
            )
        else {}
        }
    }
// scaleAllItems: apply scaleItem to every logged meal entry,
// dropping any entries where no matching food was found.
fun scaleAllItems() = (meal.meals map ((item) -> scaleItem(item)))
filter ($ != null)

// sumNutrients: add up each nutrient across every scaled meal to get daily totals. 
fun sumNutrients() = (scaleAllItems() map ((item) -> item.nutrients))
    reduce ((nutrients, acc = {}) ->
            nutrients mapObject ((value, key) ->
                { (key): (value default 0) + (acc[key] default 0) }
            )
        )

---
{
    scaledItems: scaleAllItems(),
    dailyTotals: sumNutrients()
}

%dw 2.0
output application/java
import evaluateCalories from dwl::computes::evaluateCalories
import * from dwl::thresholds::derived_targets
import evaluateProtein from dwl::computes::evaluateProtein
import evaluateSaturatedFat from dwl::computes::evaluateSaturatedFat
import evaluateFiber from dwl::computes::evaluateFiber
import evaluateAmdrRange from dwl::computes::evaluateAmdrRange
import evaluateCarbohydrate from dwl::computes::evaluateCarbohydrate
import * from dwl::computes::evaluateSodium
import rowsForMetric from dwl::thresholds::static_thresholds

var energykcal = (vars.nutritionAggregate.dailyTotals.energyKcal as Number) default 0
var calTarget = vars.userProfile.profile.dailyCaloricTarget as Number default null
var resolvedProteins = resolveProteinTarget(vars.userProfile)
var resolvedSaturatedFat= resolveSaturatedFatTarget(calTarget,vars.userProfile.conditions)
var resolvedFiber = resolveFiberTarget(calTarget)
var resolveAmdrFat = resolveAmdrTarget(amdrRanges[1], calTarget)
var resolveAmdrCarb = resolveAmdrTarget(amdrRanges[0], calTarget)
var row = rowsForMetric("carbohydrate_g")
var resolveSodium = resolveSodiumTarget(vars.userProfile.conditions)

var evalCal = evaluateCalories(energykcal,calTarget)
var evalProtein = evaluateProtein(vars.nutritionAggregate.dailyTotals.proteinG, resolvedProteins)
var evalSaturatedFat = evaluateSaturatedFat(vars.nutritionAggregate.dailyTotals.saturatedFatG,resolvedSaturatedFat)
var evalFiber = evaluateFiber(vars.nutritionAggregate.dailyTotals.dietaryFiberG,resolvedFiber)
var evalAmdrFat = evaluateAmdrRange(vars.nutritionAggregate.dailyTotals.totalFatG,resolveAmdrFat, "total_fat_g")
var evalCarbohydrate = evaluateCarbohydrate(vars.nutritionAggregate.dailyTotals.carbohydratesG,resolveAmdrCarb,row)
var evalSodium = evaluateSodium(vars.nutritionAggregate.dailyTotals.sodiumMg, resolveSodium)
fun summarizeMacrosStatus() = do {
	var allStatuses = [evalProtein.status,
    evalSaturatedFat.status,
    evalFiber.status,
    evalAmdrFat.status,
    evalSodium.status,
    evalCarbohydrate.status]
	var worstRank = max(allStatuses map (statusSeverity[$]))
	---
	severityToStatus[worstRank as String]
}
---
{
	calories: evalCal,
	macros: {
		protein: evalProtein,
		saturatedFat: evalSaturatedFat,
		fiber: evalFiber,
		fat: evalAmdrFat,
		carbohydrate: evalCarbohydrate,
		sodium: evalSodium,
		status: summarizeMacrosStatus()
	}
}

%dw 2.0
output application/java

import * from dwl::thresholds::static_thresholds
import evaluateMicronutrients from dwl::computes::evaluateMicronutrients

// compute age 
var dateOfBirth = vars.userProfile.profile.dateOfBirth
var age = do{
    var today = now() as Date
    var dob = dateOfBirth as Date
    var rawAge = today.year - dob.year
    var passedBirthday = (today.month > dob.month) or (today.month == dob.month and today.day >= dob.day)
    ---
    if ( passedBirthday ) rawAge else rawAge - 1
}
var demographic = resolveDemographic(vars.userProfile.profile.biologicalSex, age)
var conditions = vars.userProfile.conditions filter ($.isActive == true) map ($.conditionType)
var constraints = vars.userProfile.constraints filter ($.isActive == true) map ($.constraintValue)
var dailyTotals = vars.nutritionAggregate.dailyTotals 
---
evaluateMicronutrients(demographic,conditions,constraints,dailyTotals)

%dw 2.0
output application/java
import evaluateSleep from dwl::computes::evaluateSleep
import * from dwl::computes::computeSleepAggregate
import evaluateRecovery from dwl::computes::evaluateRecovery
import evaluateActiveEnergy from dwl::computes::evaluateActiveEnergy

var targetSleepDurationHrs = vars.userProfile.preferences.targetSleepDurationHrs[0]
var todaySteps = (vars.wearableStatus.dailyData.point_metrics filter ($.metric_type == "step_count")) map ($.value) reduce ((v, acc = 0) -> acc + v)
var todayActiveEnergy = vars.wearableStatus.dailyData.point_metrics filter ((item) -> item.metric_type == 'active_energy_burned')
reduce ((item, acc = 0) -> item.value + acc )

var evalSleep =
  if ( vars.wearableStatus.dailyDataAvailable ) do {
	var sleepAggregate = computeSleepAggregate(vars.wearableStatus.dailyData.sleep_sessions)
	---
	evaluateSleep(sleepAggregate.durationHrs, sleepAggregate.deepPct, sleepAggregate.remPct, targetSleepDurationHrs)
}
  else
    {
	duration_hrs: null,
	target_hrs: null,
	floor_applied: false,
	duration_status: null,
	rem_pct: null,
	rem_status: null,
	deep_pct: null,
	deep_status: null,
	status: "no_data"
}
var evalRecovery = evaluateRecovery(vars.wearableStatus)
var evalEnergy = evaluateActiveEnergy(todayActiveEnergy,vars.wearableStatus.baselineData)
---
{
	sleep: evalSleep,
	recovery: evalRecovery,
	activity: {
		steps: todaySteps,
  		active_energy_kcal: todayActiveEnergy,
  		deviation_status_low: evalEnergy.deviation_status_low,
  		deviation_status_high: evalEnergy.deviation_status_high,
  		baseline_kcal: evalEnergy.baseline_kcal default null
	}
}

%dw 2.0
output application/java

import gatherCandidates,buildRecommendations from dwl::computes::gatherCandidates
import detectCrossSignals from dwl::computes::detectCrossSignals

var gatheredCandidates = gatherCandidates(vars.nutritionDetail,vars.biometricDetail)
var recommendations = buildRecommendations(gatheredCandidates)
var primaryGoal = vars.userProfile.goals filter (() -> $.isPrimary)
var crossSignals = detectCrossSignals(vars.nutritionDetail,vars.biometricDetail,vars.userProfile.conditions,primaryGoal)
---
{
	recommendations: recommendations,
	cross_signal: crossSignals
}
